powerpagecomponent.content:
{
  "source": "{% comment %}
sections--confirmation (slot / platform-page compatible)

- Displays confirmation after payment or completion
- Driven entirely by acceptanceId
- Read-only view (no updates)

Aligned to payment section structure:
wrap → card → header → body → grid → panel(s)
{% endcomment %}

{% assign acceptanceId = request.params.acceptanceid | default: '' | strip %}

{% if acceptanceId == '' %}
  <div class="alert alert-warning">Missing acceptance id.</div>

{% else %}

{% fetchxml acc %}
<fetch top="1" mapping="logical">
  <entity name="hit_offeringacceptance">

    <attribute name="hit_offeringacceptanceid" />
    <attribute name="hit_totalamounteffective" />
    <attribute name="hit_email" />
    <attribute name="hit_stripechargeid" />

    <link-entity
      name="hit_offering"
      from="hit_offeringid"
      to="hit_offering"
      alias="off"
      link-type="outer">

      <attribute name="hit_offeringname" />

    </link-entity>

    <filter>
      <condition attribute="hit_offeringacceptanceid"
                 operator="eq"
                 value="{{ acceptanceId | escape }}" />
    </filter>

  </entity>
</fetch>
{% endfetchxml %}

{% assign acc = acc.results.entities | first %}

{% if acc %}

{% assign offeringName = acc['off.hit_offeringname'] | default: 'Offering' %}
{% assign total = acc.hit_totalamounteffective %}
{% if total.value %}{% assign total = total.value %}{% endif %}

<style>
/* ==========================================================================
   CONFIRMATION SECTION (aligned with payment)
   ========================================================================== */

.hit-confirm-wrap{
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--hit-space-7, 28px) var(--hit-space-4, 16px) var(--hit-space-10, 72px);
}

.hit-confirm-card{
  background: var(--hit-surface, #fff);
  border: 1px solid var(--hit-border, rgba(15,23,42,.10));
  border-radius: var(--hit-radius-xl, 24px);
  overflow: hidden;
  box-shadow: var(--hit-shadow-lg, 0 16px 40px rgba(15,23,42,.10));
}

.hit-confirm-head{
  padding: var(--hit-space-6, 22px) var(--hit-space-7, 26px);
  border-bottom: 1px solid var(--hit-border, rgba(15,23,42,.10));
  background: linear-gradient(to bottom, rgba(15,23,42,.02), rgba(15,23,42,0));
  text-align: center;
}

.hit-confirm-title{
  margin: 0;
  font-size: clamp(24px, 2.8vw, 34px);
  font-weight: 900;
  letter-spacing: -0.02em;
}

.hit-confirm-sub{
  margin: 10px auto 0;
  max-width: 60ch;
  color: var(--hit-muted, rgba(15,23,42,.72));
  line-height: 1.55;
}

.hit-confirm-body{
  padding: var(--hit-space-6, 20px) var(--hit-space-7, 26px) var(--hit-space-7, 26px);
}

.hit-confirm-grid{
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--hit-space-5, 18px);
  max-width: 720px;
  margin: 0 auto;
}

.hit-confirm-panel{
  border: 1px solid var(--hit-border, rgba(15,23,42,.12));
  border-radius: var(--hit-radius-lg, 18px);
  padding: var(--hit-space-5, 16px);
  background: var(--hit-panel, rgba(15,23,42,.02));
}

.hit-confirm-row{
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed rgba(15,23,42,.12);
}

.hit-confirm-row:last-child{
  border-bottom: 0;
  padding-bottom: 0;
}

.hit-confirm-label{
  font-size: 12.5px;
  color: var(--hit-muted, rgba(15,23,42,.70));
}

.hit-confirm-val{
  text-align: right;
  font-weight: 900;
  word-break: break-word;
}

.hit-confirm-actions{
  margin-top: var(--hit-space-6, 20px);
  display: flex;
  justify-content: center;
}

.hit-confirm-btn{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 18px;
  border-radius: 999px;
  border: 1px solid rgba(15,23,42,.12);
  background: var(--hit-primary, #0f172a);
  color: #fff;
  text-decoration: none;
  font-weight: 850;
}

/* ==========================================================
   HERO
   ========================================================== */

.hit-confirm-hero{
  text-align:center;
  max-width:700px;
  margin:0 auto 32px;
}

.hit-confirm-icon{
  width:84px;
  height:84px;
  margin:0 auto 20px;
  border-radius:50%;
  background:#007f89;
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:42px;
  font-weight:900;
}

.hit-confirm-amount{
  font-size:clamp(48px,6vw,72px);
  font-weight:900;
  color:#007f89;
  line-height:1;
  margin-bottom:12px;
}

.hit-confirm-message{
  font-size:clamp(24px,2.6vw,34px);
  font-weight:900;
  line-height:1.2;
  margin-bottom:16px;
}

.hit-confirm-impact{
  color:rgba(15,23,42,.70);
  line-height:1.7;
  max-width:60ch;
  margin:0 auto;
}

/* ==========================================================
   PANEL TITLES
   ========================================================== */

.hit-confirm-panel-title{
  margin:0 0 16px;
  font-size:18px;
  font-weight:900;
}

/* ==========================================================
   NEXT STEPS LIST
   ========================================================== */

.hit-confirm-list{
  margin:0;
  padding-left:20px;
}

.hit-confirm-list li{
  margin-bottom:12px;
  line-height:1.6;
}

/* ==========================================================
   BUTTON
   ========================================================== */

.hit-confirm-btn{
  background:#007f89 !important;
  border:none !important;
}

.hit-confirm-btn:hover{
  background:#006a72 !important;
}
</style>

<div class="hit-confirm-wrap">

  <div class="hit-confirm-card">

    <!-- Header -->
    <div class="hit-confirm-head">
      <h1 class="hit-confirm-title">Thank you!</h1>
      <div class="hit-confirm-sub">
        Your transaction has been successfully completed. A confirmation has been recorded and any required fulfilment will now proceed.
      </div>
    </div>

    <!-- Body -->
<div class="hit-confirm-body">

  <div class="hit-confirm-hero">

    <div class="hit-confirm-icon">
      ✓
    </div>

    <div class="hit-confirm-amount">
      ${{ total }}
    </div>

    <div class="hit-confirm-message">
      Thank you for supporting
      Disability Sport & Recreation.
    </div>

    <div class="hit-confirm-impact">
      Your contribution helps create
      inclusive opportunities for people with
      disability to participate in sport,
      recreation and community life.
    </div>

  </div>

  <div class="hit-confirm-grid">

    <div class="hit-confirm-panel">

      <h3 class="hit-confirm-panel-title">
        What Happens Next
      </h3>

      <ul class="hit-confirm-list">

        <li>
          Your donation has been successfully processed.
        </li>

        {% if acc.hit_email %}
        <li>
          A receipt has been emailed to
          <strong>{{ acc.hit_email | escape }}</strong>.
        </li>
        {% endif %}

        <li>
          Your support has been directed to
          <strong>{{ offeringName | escape }}</strong>.
        </li>

      </ul>

    </div>

    <div class="hit-confirm-panel">

      <h3 class="hit-confirm-panel-title">
        Donation Summary
      </h3>

      <div class="hit-confirm-row">
        <div class="hit-confirm-label">
          Offering
        </div>
        <div class="hit-confirm-val">
          {{ offeringName | escape }}
        </div>
      </div>

      <div class="hit-confirm-row">
        <div class="hit-confirm-label">
          Amount
        </div>
        <div class="hit-confirm-val">
          ${{ total }}
        </div>
      </div>

      {% if acc.hit_email %}
      <div class="hit-confirm-row">
        <div class="hit-confirm-label">
          Receipt Email
        </div>
        <div class="hit-confirm-val">
          {{ acc.hit_email | escape }}
        </div>
      </div>
      {% endif %}

      {% if acc.hit_stripechargeid %}
      <div class="hit-confirm-row">
        <div class="hit-confirm-label">
          Reference
        </div>
        <div class="hit-confirm-val">
          {{ acc.hit_stripechargeid }}
        </div>
      </div>
      {% endif %}

    </div>

    <div class="hit-confirm-actions">

      <a href="/"
         class="hit-confirm-btn">
        Return Home
      </a>

    </div>

  </div>

</div>
  </div>

</div>

{% else %}
  <div class="alert alert-warning">Confirmation not found</div>
{% endif %}

{% endif %}
"
}
